xql_query:
// ============================================================
// Rule: CTX_Deno Runtime Remote JavaScript Execution with Allow-All Permissions
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Deno Runtime Remote JavaScript Execution with Allow-All Permissions.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1059.007 - Command and Scripting Interpreter: JavaScript

// Title: CTX - Deno Runtime Remote JavaScript Execution with Allow-All Permissions
// Description: Detecta execução de Deno com permissão ampla (-A/--allow-all) buscando JavaScript remoto.
// Este padrão é incomum em endpoints corporativos e pode indicar execução de RAT ou payload malicioso.
// MITRE ATT&CK: T1059.007 (JavaScript), T1105 (Ingress Tool Transfer)
//
// NOTA TH: Deno é runtime JavaScript/TypeScript que por design executa código remoto via URL.
// Em ambientes corporativos, deno.exe é raramente legítimo — qualquer ocorrência deve ser investigada.
// --allow-all ou -A desabilita o modelo de segurança sandbox do Deno, concedendo acesso total ao SO.
// Pivô: verificar parent process, conexões de rede subsequentes e SHA256 do deno.exe.
//
// NOTA SINTAXE: O padrão (-[aA]) cobre tanto -a quanto -A (Deno usa -A maiúsculo como alias).
// O padrão (^|\s) garante que -A no início da cadeia de args também seja capturado.
// Extensão .ts também coberta: Deno executa TypeScript nativo, não apenas .js.

config case_sensitive = false
| dataset = xdr_data

// Escopo: eventos de processo em Windows
| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.PROCESS
    and event_sub_type = ENUM.PROCESS_START

| fields
    _time,
    agent_hostname,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_process_image_name,
    action_process_image_path,
    action_process_image_command_line,
    action_process_image_sha256,
    causality_actor_process_image_name,
    causality_actor_process_command_line

| alter action_cmd = lowercase(action_process_image_command_line)

// Filtro 1: processo é deno.exe
| filter action_process_image_name = "deno.exe"

// Filtro 2: flag de permissão ampla — corrigido para cobrir -A no início de argumentos
// Nota: -a e -A são capturados via [-aA]; (^|\s) evita falso match em nomes de arquivo como "--data"
| filter action_cmd ~= "(^|\\s)--allow-all(\\s|$)" or action_cmd ~= "(^|\\s)-[aA](\\s|$)"

// Filtro 3: script carregado via URL remota — inclui .ts (TypeScript nativo do Deno)
| filter action_cmd ~= "https?://[^\\s\"']+\\.(js|ts|mjs)"

| sort desc _time
